 HTMLFormElement.prototype.submit=function(){var f=this;if(f.__mpok||!/\/webhook\/cbs-docs-zip/.test(f.action||'')){return sub.call(f);}
  var inp=f.querySelector('input[name=d]'),d=null;try{d=JSON.parse(inp.value);}catch(x){}
  var files=(d&&d.files||[]).filter(function(x){return x&&x.u;}),n=files.length+((d&&d.gen)||[]).length;
  if(n<2){f.__mpok=1;return sub.call(f);}
  choose(n,d.label).then(function(c){if(c==='zip'){f.__mpok=1;sub.call(f);}else if(c==='pdf')merge(d.label||'Documents',files,d.gen||[]);f.remove&&setTimeout(function(){try{f.remove();}catch(x){}},2000);});};
 /* site file / close-out pack links (cbs-cdm?...&a=pack) */
 document.addEventListener('click',function(ev){var a=ev.target.closest&&ev.target.closest('a[href*="cbs-cdm?"]');if(!a||a.id==='dl'||a.__mpok||!/[?&]a=pack/.test(a.getAttribute('href')))return;
  ev.preventDefault();ev.stopImmediatePropagation();var href=a.getAttribute('href'),u=new URL(href,location.href),job=u.searchParams.get('job'),fs=(u.searchParams.get('f')||'').split(',').filter(Boolean).map(Number);
  choose('the',a.textContent.trim()||'Site file').then(function(c){if(c==='zip'){a.__mpok=1;a.click();setTimeout(function(){a.__mpok=0;},500);return;}if(c==='pdf')packPdf(job,fs);});},true);
 function packPdf(job,fs){
   fetch('/webhook/cbs-cdm?job='+encodeURIComponent(job),{cache:'no-store'}).then(function(r){return r.json();}).then(function(st){var files=[];(st.sections||[]).forEach(function(sec){if(fs.length&&fs.indexOf(sec.no)<0)return;(sec.items||[]).forEach(function(it){if(it.url&&/sharepoint\.com/i.test(it.url))files.push({u:it.url,n:it.title,f:sec.folder});else if(it.gen)files.push({u:'',n:it.title+' (generated - zip only)',f:sec.folder});});});
    if(!files.filter(function(x){return x.u;}).length){alert('There are no stored documents to put in a PDF. The generated summaries are in the zip download.');return;}
    merge('Job '+job+' - '+(fs.length===1&&fs[0]===13?'Close-out pack':'Site file'),files,[]);}).catch(function(){alert('Could not load the document list. Try the zip download.');});}
}
